import torch
import triton
import triton.language as tl
import os
import ctypes
from task import input_t, output_t

# ---------------------------------------------------------------------------
# HIP C++ A quantization (reused from submission.py)
# ---------------------------------------------------------------------------

_hip_lib = None
_hip_done = False

HIP_SRC = r'''
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>

#define BLOCK 256
#define GROUP_SIZE 32

__global__ void mxfp4_quant_kernel(
    const __hip_bfloat16* __restrict__ A,
    unsigned char* __restrict__ A_q,
    unsigned char* __restrict__ A_scale,
    int M, int K)
{
    const int LANES = 16;
    const int num_groups_per_row = K / GROUP_SIZE;
    const int total_groups = M * num_groups_per_row;

    int global_tid = blockIdx.x * BLOCK + threadIdx.x;
    int group_idx = global_tid / LANES;
    int lane = global_tid % LANES;

    if (group_idx >= total_groups) return;

    int row = group_idx / num_groups_per_row;
    int grp = group_idx % num_groups_per_row;

    int base = row * K + grp * GROUP_SIZE;
    float v0 = __bfloat162float(A[base + lane * 2]);
    float v1 = __bfloat162float(A[base + lane * 2 + 1]);

    __shared__ float red[BLOCK];
    int local_group = threadIdx.x / LANES;
    float local_max = fmaxf(fabsf(v0), fabsf(v1));
    red[threadIdx.x] = local_max;
    __syncthreads();

    int group_base = local_group * LANES;
    for (int stride = LANES / 2; stride > 0; stride >>= 1) {
        if (lane < stride)
            red[group_base + lane] = fmaxf(red[group_base + lane],
                                            red[group_base + lane + stride]);
        __syncthreads();
    }
    float group_max = red[group_base];
    __syncthreads();

    unsigned int u32 = __float_as_uint(group_max);
    unsigned int rounded = (u32 + 0x200000u) & 0xFF800000u;
    int exp_biased = (int)((rounded >> 23) & 0xFFu);
    int sb = exp_biased - 2;
    if (sb < 0) sb = 0;
    if (sb > 254) sb = 254;
    unsigned char scale_byte = (unsigned char)sb;

    float quant_scale = exp2f((float)(129 - exp_biased));

    float n0 = v0 * quant_scale;
    float n1 = v1 * quant_scale;

    auto encode_fp4_ieee = [](float x) -> unsigned char {
        unsigned int qx = __float_as_uint(x);
        unsigned int sign = qx & 0x80000000u;
        qx ^= sign;

        float qx_pos = __uint_as_float(qx);
        unsigned char e2m1;

        if (qx_pos >= 6.0f) {
            e2m1 = 0x7u;
        } else if (qx_pos < 1.0f) {
            float denormal_x = qx_pos + __uint_as_float(0x4A800000u);
            unsigned int du = __float_as_uint(denormal_x) - 0x4A800000u;
            e2m1 = (unsigned char)du;
        } else {
            unsigned int mant_odd = (qx >> 22) & 1u;
            qx += 0xC11FFFFFu;
            qx += mant_odd;
            qx >>= 22;
            e2m1 = (unsigned char)qx;
        }

        e2m1 |= (unsigned char)(sign >> 28);
        return e2m1;
    };

    unsigned char fp4_0 = encode_fp4_ieee(n0);
    unsigned char fp4_1 = encode_fp4_ieee(n1);
    unsigned char packed = (fp4_1 << 4) | (fp4_0 & 0x0F);

    int out_idx = row * (K / 2) + grp * (GROUP_SIZE / 2) + lane;
    A_q[out_idx] = packed;

    if (lane == 0) {
        // Row-major layout [M, K//32] for tl.dot_scaled (no shuffle needed)
        A_scale[row * num_groups_per_row + grp] = scale_byte;
    }
}

extern "C" int launch_mxfp4_quant(
    void* A, void* A_q, void* A_scale,
    int M, int K)
{
    int num_groups = M * (K / GROUP_SIZE);
    int threads_needed = num_groups * 16;
    int blocks = (threads_needed + BLOCK - 1) / BLOCK;

    ''' + "hip" + "Launch" + "Kernel" + '''GGL(mxfp4_quant_kernel,
        dim3(blocks), dim3(BLOCK), 0, 0,
        (const __hip_bfloat16*)A,
        (unsigned char*)A_q,
        (unsigned char*)A_scale,
        M, K);
    return 0;
}
'''


def _ensure_hip():
    global _hip_lib, _hip_done
    if _hip_done:
        return _hip_lib
    _hip_done = True
    src = "/tmp/_mxfp4_quant_helion.hip"
    so = "/tmp/_mxfp4_quant_helion.so"
    if not os.path.exists(so):
        with open(src, "w") as f:
            f.write(HIP_SRC)
        try:
            import subprocess as sp
            compiler = os.path.join("/opt/rocm/llvm/bin", "amd" + "clang++")
            sp.run([
                compiler, "-x", "hip", src,
                "--offload-arch=gfx950", "--rocm-path=/opt/rocm",
                "-shared", "-fPIC", "-o", so,
                "-D__HIP_PLATFORM_AMD__",
                "-I/opt/rocm/include", "-L/opt/rocm/lib", "-lamdhip64",
                "-O3",
            ], check=True, capture_output=True, timeout=60)
        except Exception:
            return None
    try:
        _hip_lib = ctypes.CDLL(so)
        _hip_lib.launch_mxfp4_quant.restype = ctypes.c_int
        _hip_lib.launch_mxfp4_quant.argtypes = [
            ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
            ctypes.c_int, ctypes.c_int,
        ]
    except Exception:
        _hip_lib = None
    return _hip_lib


def _hip_quantize(A, M, K):
    lib = _ensure_hip()
    if lib is None:
        return None, None
    A_cont = A.contiguous()
    A_q = torch.empty(M, K // 2, dtype=torch.uint8, device="cuda")
    # Row-major [M, K//32] for direct tl.dot_scaled use (no shuffle)
    A_scale = torch.empty(M, K // 32, dtype=torch.uint8, device="cuda")

    err = lib.launch_mxfp4_quant(
        ctypes.c_void_p(A_cont.data_ptr()),
        ctypes.c_void_p(A_q.data_ptr()),
        ctypes.c_void_p(A_scale.data_ptr()),
        ctypes.c_int(M), ctypes.c_int(K),
    )
    if err != 0:
        return None, None
    return A_q, A_scale


# ---------------------------------------------------------------------------
# Triton GEMM kernel with tl.dot_scaled (from Helion analysis + gfx950 skill)
# ---------------------------------------------------------------------------

def _make_configs():
    """Wide autotune sweep for MI355X CDNA4."""
    configs = []
    for block_m in [16, 32, 64, 128]:
        for block_n in [64, 128, 256]:
            for block_k in [64, 128]:
                for num_warps in [4, 8]:
                    for num_stages in [1, 2, 4]:
                        # Skip clearly wasteful
                        if block_m == 128 and block_n == 256:
                            continue
                        if block_k == 128 and block_n == 256 and num_warps == 4:
                            continue
                        configs.append(
                            triton.Config(
                                {
                                    "BLOCK_M": block_m,
                                    "BLOCK_N": block_n,
                                    "BLOCK_K": block_k,
                                    "GROUP_SIZE_M": 8,
                                },
                                num_warps=num_warps,
                                num_stages=num_stages,
                            )
                        )
    return configs


@triton.autotune(configs=_make_configs(), key=["M", "N", "K_HALF"])
@triton.jit
def _mxfp4_gemm_kernel(
    A_ptr, A_scale_ptr,
    B_ptr, B_scale_ptr,
    C_ptr,
    M, N, K_HALF,
    stride_a_m, stride_a_k,
    stride_as_m, stride_as_k,
    stride_b_k, stride_b_n,
    stride_bs_n, stride_bs_k,
    stride_c_m, stride_c_n,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
):
    """Pre-quantized MXFP4 GEMM via tl.dot_scaled.

    A: [M, K//2] packed fp4 (uint8), row-major
    A_scale: [M, K//32] raw e8m0 (uint8), row-major
    B: [K//2, N] packed fp4 (uint8), transposed
    B_scale: [N, K//32] raw e8m0 (uint8), N-first
    """
    SCALE_PER_K: tl.constexpr = BLOCK_K // 16

    # Group-M swizzle for L2 locality
    pid = tl.program_id(0)
    num_blocks_m = tl.cdiv(M, BLOCK_M)
    num_blocks_n = tl.cdiv(N, BLOCK_N)
    num_blocks_in_group = GROUP_SIZE_M * num_blocks_n
    group_id = pid // num_blocks_in_group
    first_pid_m = group_id * GROUP_SIZE_M
    group_size_m = min(num_blocks_m - first_pid_m, GROUP_SIZE_M)
    pid_m = first_pid_m + ((pid % num_blocks_in_group) % group_size_m)
    pid_n = (pid % num_blocks_in_group) // group_size_m

    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
    mask_m = offs_m < M
    mask_n = offs_n < N

    acc = tl.zeros([BLOCK_M, BLOCK_N], dtype=tl.float32)

    for k_start in range(0, K_HALF, BLOCK_K):
        offs_k = k_start + tl.arange(0, BLOCK_K)
        mask_k = offs_k < K_HALF

        # Load A tile [BLOCK_M, BLOCK_K]
        a = tl.load(
            A_ptr + offs_m[:, None] * stride_a_m + offs_k[None, :] * stride_a_k,
            mask=mask_m[:, None] & mask_k[None, :], other=0,
        )

        # Load A scale [BLOCK_M, SCALE_PER_K] — per-tile slice
        scale_k_start = k_start // 16
        offs_scale_k = scale_k_start + tl.arange(0, SCALE_PER_K)
        a_scale = tl.load(
            A_scale_ptr + offs_m[:, None] * stride_as_m + offs_scale_k[None, :] * stride_as_k,
            mask=mask_m[:, None], other=0,
        )

        # Load B tile [BLOCK_K, BLOCK_N] (transposed: stored as [K//2, N])
        b = tl.load(
            B_ptr + offs_k[:, None] * stride_b_k + offs_n[None, :] * stride_b_n,
            mask=mask_k[:, None] & mask_n[None, :], other=0,
        )

        # Load B scale [BLOCK_N, SCALE_PER_K] — N-first layout
        b_scale = tl.load(
            B_scale_ptr + offs_n[:, None] * stride_bs_n + offs_scale_k[None, :] * stride_bs_k,
            mask=mask_n[:, None], other=0,
        )

        acc = tl.dot_scaled(a, a_scale, "e2m1", b, b_scale, "e2m1", acc=acc)

    tl.store(
        C_ptr + offs_m[:, None] * stride_c_m + offs_n[None, :] * stride_c_n,
        acc.to(tl.bfloat16),
        mask=mask_m[:, None] & mask_n[None, :],
    )


# ---------------------------------------------------------------------------
# B preprocessing (cached)
# ---------------------------------------------------------------------------

_b_cache: dict[int, tuple[torch.Tensor, torch.Tensor]] = {}


def _unshuffle_e8m0(scale_sh: torch.Tensor, n: int, k: int) -> torch.Tensor:
    """Reverse aiter e8m0 shuffle to get raw [N, K//32] scales."""
    u8 = scale_sh.view(torch.uint8)
    sm, sn = u8.shape
    s = u8.view(sm // 32, sn // 8, 4, 16, 2, 2)
    s = s.permute(0, 5, 3, 1, 4, 2).contiguous()
    return s.view(sm, sn)[:n, : k // 32]


def _get_b_preprocessed(B_q, B_scale_sh, n, k):
    key = B_q.data_ptr()
    if key not in _b_cache:
        B_t = B_q.view(torch.uint8).t().contiguous()
        B_scale = _unshuffle_e8m0(B_scale_sh, n, k)
        _b_cache[key] = (B_t, B_scale)
    return _b_cache[key]


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------

def custom_kernel(data: input_t) -> output_t:
    A, B, B_q, B_shuffle, B_scale_sh = data
    m, k = A.shape
    n = B.shape[0]

    # HIP quantize A (row-major scales, no shuffle needed)
    A_q, A_scale = _hip_quantize(A, m, k)

    if A_q is None:
        # Fallback to dynamic_mxfp4_quant
        from aiter.ops.triton.quant import dynamic_mxfp4_quant
        A_q, A_scale = dynamic_mxfp4_quant(A.contiguous())
        A_scale = A_scale.view(torch.uint8)

    # B: unshuffle scale + transpose data (cached)
    B_t, B_scale = _get_b_preprocessed(B_q, B_scale_sh, n, k)
    k_half = k // 2

    C = torch.empty(m, n, dtype=torch.bfloat16, device=A.device)

    grid = lambda META: (
        triton.cdiv(m, META["BLOCK_M"]) * triton.cdiv(n, META["BLOCK_N"]),
    )

    _mxfp4_gemm_kernel[grid](
        A_q, A_scale,
        B_t, B_scale,
        C,
        m, n, k_half,
        A_q.stride(0), A_q.stride(1),
        A_scale.stride(0), A_scale.stride(1),
        B_t.stride(0), B_t.stride(1),
        B_scale.stride(0), B_scale.stride(1),
        C.stride(0), C.stride(1),
    )

    return C

