    A_cont = A.contiguous()
    A_q = torch.empty(M, K // 2, dtype=torch.uint8, device="cuda")

    # Match dynamic_mxfp4_quant exactly:
    # blockscale_e8m0 = torch.empty((K//32, M), dtype=uint8).T
    # This is shape (M, K//32) with column-major strides (1, M)
    num_groups = K // 32
    A_scale = torch.empty(
