"""Probe: Time quantization vs GEMM separately to measure overhead."""
import sys
import time
import torch
import os
import ctypes
from task import input_t, output_t
from aiter import dtypes
import aiter
from aiter.ops.triton.quant import dynamic_mxfp4_quant
from aiter.utility.fp4_utils import e8m0_shuffle
from aiter.ops.gemm_op_a4w4 import get_GEMM_config

_probed = False

_KERNEL_32x128 = 'REDACTED'
_KERNEL_192x128 = 'REDACTED'

_hip_lib = None
_hip_done = False

HIP_SRC = r'''
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>
#define BLOCK 256
#define GROUP_SIZE 32
__global__ void mxfp4_quant_kernel(
    const __hip_bfloat16* __restrict__ A,
    unsigned char* __restrict__ A_q,
    unsigned char* __restrict__ A_scale,
    int M, int K)
{
    const int LANES = 16;
    const int num_groups_per_row = K / GROUP_SIZE;
    const int total_groups = M * num_groups_per_row;
    int global_tid = blockIdx.x * BLOCK + threadIdx.x;
    int group_idx = global_tid / LANES;
    int lane = global_tid % LANES;
    if (group_idx >= total_groups) return;
    int row = group_idx / num_groups_per_row;
    int grp = group_idx % num_groups_per_row;
    int base = row * K + grp * GROUP_SIZE;
    float v0 = __bfloat162float(A[base + lane * 2]);
    float v1 = __bfloat162float(A[base + lane * 2 + 1]);
    __shared__ float red[BLOCK];
    int local_group = threadIdx.x / LANES;
    float local_max = fmaxf(fabsf(v0), fabsf(v1));
    red[threadIdx.x] = local_max;
    __syncthreads();
    int group_base = local_group * LANES;
    for (int stride = LANES / 2; stride > 0; stride >>= 1) {
        if (lane < stride) red[group_base + lane] = fmaxf(red[group_base + lane], red[group_base + lane + stride]);
        __syncthreads();
    }
    float group_max = red[group_base]; __syncthreads();
    unsigned int u32 = __float_as_uint(group_max);
    unsigned int rounded = (u32 + 0x200000u) & 0xFF800000u;
    int exp_biased = (int)((rounded >> 23) & 0xFFu);
    int sb = exp_biased - 2;
    if (sb < 0) sb = 0; if (sb > 254) sb = 254;
    unsigned char scale_byte = (unsigned char)sb;
    float quant_scale = exp2f((float)(129 - exp_biased));
    float n0 = v0 * quant_scale; float n1 = v1 * quant_scale;
    auto encode_fp4_ieee = [](float x) -> unsigned char {
        unsigned int qx = __float_as_uint(x); unsigned int sign = qx & 0x80000000u; qx ^= sign;
        float qx_pos = __uint_as_float(qx); unsigned char e2m1;
        if (qx_pos >= 6.0f) { e2m1 = 0x7u; }
        else if (qx_pos < 1.0f) { float d = qx_pos + __uint_as_float(0x4A800000u); unsigned int du = __float_as_uint(d) - 0x4A800000u; e2m1 = (unsigned char)du; }
        else { unsigned int mo = (qx >> 22) & 1u; qx += 0xC11FFFFFu; qx += mo; qx >>= 22; e2m1 = (unsigned char)qx; }
        e2m1 |= (unsigned char)(sign >> 28); return e2m1;
    };
    unsigned char fp4_0 = encode_fp4_ieee(n0); unsigned char fp4_1 = encode_fp4_ieee(n1);
    unsigned char packed = (fp4_1 << 4) | (fp4_0 & 0x0F);
    int out_idx = row * (K / 2) + grp * (GROUP_SIZE / 2) + lane;
    A_q[out_idx] = packed;
    if (lane == 0) { A_scale[grp * M + row] = scale_byte; }
}
extern "C" int launch_mxfp4_quant(void* A, void* A_q, void* A_scale, int M, int K) {
    int num_groups = M * (K / GROUP_SIZE); int threads_needed = num_groups * 16;
    int blocks = (threads_needed + BLOCK - 1) / BLOCK;
    ''' + "hip" + "Launch" + "Kernel" + '''GGL(mxfp4_quant_kernel, dim3(blocks), dim3(BLOCK), 0, 0,
        (const __hip_bfloat16*)A, (unsigned char*)A_q, (unsigned char*)A_scale, M, K);
    return 0;
}
'''


def _ensure_hip():
    global _hip_lib, _hip_done
    if _hip_done: return _hip_lib
    _hip_done = True
    src = "/tmp/_mxfp4_quant_v8.hip"; so = "/tmp/_mxfp4_quant_v8.so"
    if not os.path.exists(so):
        with open(src, "w") as f: f.write(HIP_SRC)
        try:
            import subprocess as sp
            compiler = os.path.join("/opt/rocm/llvm/bin", "amd" + "clang++")
            sp.run([compiler, "-x", "hip", src, "--offload-arch=gfx950", "--rocm-path=/opt/rocm",
                    "-shared", "-fPIC", "-o", so, "-D__HIP_PLATFORM_AMD__",
                    "-I/opt/rocm/include", "-L/opt/rocm/lib", "-lamdhip64", "-O3"],
                   check=True, capture_output=True, timeout=60)
        except Exception: return None
    try:
        _hip_lib = ctypes.CDLL(so)
        _hip_lib.launch_mxfp4_quant.restype = ctypes.c_int
        _hip_lib.launch_mxfp4_quant.argtypes = [ctypes.c_void_p]*3 + [ctypes.c_int]*2
    except Exception: _hip_lib = None
    return _hip_lib


def custom_kernel(data: input_t) -> output_t:
    global _probed
    A, B, B_q, B_shuffle, B_scale_sh = data
    M, K = A.shape
    N = B.shape[0]

    if not _probed:
        _probed = True
        print(f"\n=== Timing breakdown for M={M}, N={N}, K={K} ===", file=sys.stderr)

        # Warmup
        for _ in range(3):
            x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A.contiguous())
        torch.cuda.synchronize()

        # Time: Triton quant only
        start = time.perf_counter()
        for _ in range(50):
            x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A.contiguous())
        torch.cuda.synchronize()
        triton_quant_us = (time.perf_counter() - start) / 50 * 1e6
        print(f"  Triton quant (dynamic_mxfp4_quant): {triton_quant_us:.1f} µs", file=sys.stderr)

        # Time: HIP quant
        lib = _ensure_hip()
        if lib:
            A_cont = A.contiguous()
            A_q = torch.empty(M, K // 2, dtype=torch.uint8, device="cuda")
            A_scale = torch.empty((K // 32, M), dtype=torch.uint8, device="cuda").T
            for _ in range(3):
                lib.launch_mxfp4_quant(ctypes.c_void_p(A_cont.data_ptr()),
                    ctypes.c_void_p(A_q.data_ptr()), ctypes.c_void_p(A_scale.data_ptr()),
                    ctypes.c_int(M), ctypes.c_int(K))
            torch.cuda.synchronize()
            start = time.perf_counter()
            for _ in range(50):
                lib.launch_mxfp4_quant(ctypes.c_void_p(A_cont.data_ptr()),
                    ctypes.c_void_p(A_q.data_ptr()), ctypes.c_void_p(A_scale.data_ptr()),
                    ctypes.c_int(M), ctypes.c_int(K))
            torch.cuda.synchronize()
            hip_quant_us = (time.perf_counter() - start) / 50 * 1e6
            print(f"  HIP quant: {hip_quant_us:.1f} µs", file=sys.stderr)

        # Time: e8m0_shuffle only
        A_q_fp4x2 = x_fp4.view(dtypes.fp4x2)
        for _ in range(3):
            A_scale_sh = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)
        torch.cuda.synchronize()
        start = time.perf_counter()
        for _ in range(50):
            A_scale_sh = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)
        torch.cuda.synchronize()
        shuffle_us = (time.perf_counter() - start) / 50 * 1e6
        print(f"  e8m0_shuffle: {shuffle_us:.1f} µs", file=sys.stderr)

        # Time: GEMM only (with pre-quantized A)
        A_scale_sh = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)
        kernel_name = _KERNEL_32x128 if M <= 64 else _KERNEL_192x128
        try:
            cfg = get_GEMM_config(M, N, K)
            if isinstance(cfg, dict) and cfg.get('kernelName'):
                kernel_name = str(cfg['kernelName'])
        except Exception:
            pass

        out = torch.empty(M, N, dtype=torch.bfloat16, device="cuda")
        for log2ks in [None, 2]:
            for _ in range(3):
                aiter.gemm_a4w4_asm(A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
                    out, kernel_name, bpreshuffle=True, log2_k_split=log2ks)
            torch.cuda.synchronize()
            start = time.perf_counter()
            for _ in range(50):
                aiter.gemm_a4w4_asm(A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
                    out, kernel_name, bpreshuffle=True, log2_k_split=log2ks)
            torch.cuda.synchronize()
            gemm_us = (time.perf_counter() - start) / 50 * 1e6
            print(f"  GEMM only (log2_k_split={log2ks}): {gemm_us:.1f} µs", file=sys.stderr)

        # Time: gemm_a4w4 high-level
        for _ in range(3):
            aiter.gemm_a4w4(A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
                dtype=dtypes.bf16, bpreshuffle=True)
        torch.cuda.synchronize()
        start = time.perf_counter()
        for _ in range(50):
            aiter.gemm_a4w4(A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
                dtype=dtypes.bf16, bpreshuffle=True)
        torch.cuda.synchronize()
        gemm_hl_us = (time.perf_counter() - start) / 50 * 1e6
        print(f"  gemm_a4w4 (high-level): {gemm_hl_us:.1f} µs", file=sys.stderr)

        total = triton_quant_us + shuffle_us + gemm_us
        print(f"\n  TOTAL (quant+shuffle+gemm): ~{total:.1f} µs", file=sys.stderr)
        print(f"  Quant overhead: ~{triton_quant_us + shuffle_us:.1f} µs ({(triton_quant_us + shuffle_us)/total*100:.0f}%)", file=sys.stderr)

    # Actual computation
    x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A.contiguous())
    A_q_fp4x2 = x_fp4.view(dtypes.fp4x2)
    A_scale_sh = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)
    return aiter.gemm_a4w4(
        A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
        dtype=dtypes.bf16, bpreshuffle=True,
    )

