            return str(cfg)
    except Exception:
        pass
    return _KERNEL_32x128 if M <= 64 else _KERNEL_192x128


def custom_kernel(data: input_t) -> output_t:
    global _probed
    A, B, B_q, B_shuffle, B_scale_sh = data
    M, K = A.shape
