    # ---- Probe: first time we see this shape ----
    if key not in _probed:
        _probed.add(key)
        print(f"\n=== Probe: M={M}, N={N}, K={K} ===", file=sys.stderr)

        if lib is None:
            print("  HIP lib failed to compile", file=sys.stderr)
        else:
            A_cont = A.contiguous()
            A_q = torch.empty(M, K // 2, dtype=torch.uint8, device="cuda")
            A_scale = torch.zeros(sm * sn, dtype=torch.uint8, device="cuda")
            kernel_name = _get_kernel_name(M, N, K)
            out = torch.empty(M, N, dtype=torch.bfloat16, device="cuda")

            # Warmup
            for _ in range(5):
                A_scale.zero_()
                lib.launch_mxfp4_quant_fused(
                    ctypes.c_void_p(A_cont.data_ptr()),
