                    ctypes.c_void_p(A_scale.data_ptr()),
                    ctypes.c_int(M), ctypes.c_int(K),
                    ctypes.c_int(sm), ctypes.c_int(sn),
                )
                A_q_fp4x2 = A_q.view(dtypes.fp4x2)
                A_scale_sh = A_scale.view(sm, sn).view(dtypes.fp8_e8m0)
                aiter.gemm_a4w4_asm(A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
                                    out, kernel_name, bpreshuffle=True, log2_k_split=2)
            torch.cuda.synchronize()

            # Time torch.zeros alloc vs zero_() reuse
            # a) Allocation each time
            start = time.perf_counter()
            for _ in range(100):
                buf = torch.zeros(sm * sn, dtype=torch.uint8, device="cuda")
                _ = buf.data_ptr()
            torch.cuda.synchronize()
            alloc_us = (time.perf_counter() - start) / 100 * 1e6
