                                        out, kernel_name, bpreshuffle=True, log2_k_split=log2_ks)
                torch.cuda.synchronize()
                gemm_us = (time.perf_counter() - start) / 50 * 1e6
                print(f"  log2_k_split={log2_ks}: GEMM={gemm_us:.1f} µs", file=sys.stderr)

            # Full pipeline timing (quant + GEMM) with best guessed config
            A_scale_static = torch.empty(sm * sn, dtype=torch.uint8, device="cuda")
            for log2_ks in [2, 3]:
                for _ in range(3):
