        _hip_lib = ctypes.CDLL(so)
        _hip_lib.launch_mxfp4_quant_fused.restype = ctypes.c_int
        _hip_lib.launch_mxfp4_quant_fused.argtypes = [
            ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
            ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int,
        ]
    except Exception:
        _hip_lib = None
    return _hip_lib


def _get_bufs(M, K, N):
    mk_key = (M, K)
    if mk_key not in _A_q_buf:
        _A_q_buf[mk_key] = torch.empty(M, K // 2, dtype=torch.uint8, device="cuda")
    if mk_key not in _scale_buf:
        sm = ((M + 255) // 256) * 256
        sn = ((K // 32 + 7) // 8) * 8
        _scale_buf[mk_key] = torch.zeros(sm * sn, dtype=torch.uint8, device="cuda")
    mn_key = (M, N)
    if mn_key not in _out_buf:
        _out_buf[mn_key] = torch.empty(M, N, dtype=torch.bfloat16, device="cuda")
    return _A_q_buf[mk_key], _scale_buf[mk_key], _out_buf[mn_key]


def _run_quant(A_cont, lib, M, K, A_q_buf, scale_buf):
    num_groups_k = K // 32
    sm = ((M + 255) // 256) * 256
    sn = ((num_groups_k + 7) // 8) * 8
    err = lib.launch_mxfp4_quant_fused(
        ctypes.c_void_p(A_cont.data_ptr()),
        ctypes.c_void_p(A_q_buf.data_ptr()),
        ctypes.c_void_p(scale_buf.data_ptr()),
        ctypes.c_int(M), ctypes.c_int(K),
        ctypes.c_int(sm), ctypes.c_int(sn),
    )
    return err, sm, sn


def _sweep_gemm(label, A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh, out_buf,
                kernel_name, M, N, K):
    """Sweep split-K values and print timing."""
    n_tiles = (N + 127) // 128
    m_tiles = (M + (191 if "192" in kernel_name else 31)) // (192 if "192" in kernel_name else 32)
    base_blocks = n_tiles * m_tiles
    print(f"\n  {label} (base {base_blocks} blocks, N-tiles={n_tiles} M-tiles={m_tiles}):",
          file=sys.stderr)
    best_ks = None
    best_us = float('inf')
    for ks in [None, 1, 2, 3, 4]:
        torch.cuda.synchronize()
        t0 = torch.cuda.Event(enable_timing=True)
        t1 = torch.cuda.Event(enable_timing=True)
        t0.record()
        try:
            aiter.gemm_a4w4_asm(
                A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
                out_buf, kernel_name,
                bpreshuffle=True,
                log2_k_split=ks,
            )
            t1.record()
            torch.cuda.synchronize()
            us = t0.elapsed_time(t1) * 1000
            split = 2**ks if ks is not None else 1
            total_blocks = base_blocks * split
            print(f"    ks={ks} ({total_blocks} blocks): {us:.2f} µs", file=sys.stderr)
            if us < best_us:
                best_us = us
                best_ks = ks
        except Exception as ex:
            print(f"    ks={ks}: ERROR {ex}", file=sys.stderr)
    print(f"  → Best: ks={best_ks} = {best_us:.2f} µs", file=sys.stderr)
    return best_ks, best_us


def _probe_shape(A, B_shuffle, B_scale_sh, lib):
    M, K = A.shape
    N = B_shuffle.shape[0]
    A_q_buf, scale_buf, out_buf = _get_bufs(M, K, N)
    A_cont = A.contiguous()
    err, sm, sn = _run_quant(A_cont, lib, M, K, A_q_buf, scale_buf)
    if err != 0:
        return None, None

    A_q_fp4x2 = A_q_buf.view(dtypes.fp4x2)
    A_scale_sh = scale_buf.view(sm, sn).view(dtypes.fp8_e8m0)

    print(f"\n=== Probe M={M} K={K} N={N} ===", file=sys.stderr)

    # Sweep both kernels
    best32_ks, best32_us = _sweep_gemm(
        "32x128", A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
        out_buf, _KERNEL_32x128, M, N, K
    )
    best192_ks, best192_us = _sweep_gemm(
        "192x128", A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
        out_buf, _KERNEL_192x128, M, N, K
    )

    overall_best = "32x128" if best32_us <= best192_us else "192x128"
    overall_ks = best32_ks if best32_us <= best192_us else best192_ks
    overall_us = min(best32_us, best192_us)
    print(f"  WINNER: {overall_best} ks={overall_ks} = {overall_us:.2f} µs", file=sys.stderr)
    print("=== End probe ===", file=sys.stderr)

    # Return result using current production config
    if M <= 64:
        kn, ks = _KERNEL_32x128, None
    else:
        kn, ks = _KERNEL_192x128, None
    return aiter.gemm_a4w4_asm(
        A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
        out_buf, kn, bpreshuffle=True, log2_k_split=ks,
    )


def custom_kernel(data: input_t) -> output_t:
    global _probed_shapes
    A, B, B_q, B_shuffle, B_scale_sh = data
    M, K = A.shape
    N = B.shape[0]

    lib = _ensure_hip()

    # Probe M=64 and M=256 on first call for each shape
    shape_key = (M, K, N)
    if M in (64, 256) and shape_key not in _probed_shapes and lib is not None:
        _probed_shapes.add(shape_key)
        result = _probe_shape(A, B_shuffle, B_scale_sh, lib)
        if result is not None:
            return result

    # Normal production path
    if lib is not None:
        num_groups_k = K // 32
        sm = ((M + 255) // 256) * 256
        sn = ((num_groups_k + 7) // 8) * 8

        A_q_buf, scale_buf, out_buf = _get_bufs(M, K, N)
        A_cont = A.contiguous()

        err = lib.launch_mxfp4_quant_fused(
            ctypes.c_void_p(A_cont.data_ptr()),
            ctypes.c_void_p(A_q_buf.data_ptr()),
            ctypes.c_void_p(scale_buf.data_ptr()),
            ctypes.c_int(M), ctypes.c_int(K),
            ctypes.c_int(sm), ctypes.c_int(sn),
        )
        if err == 0:
            A_q_fp4x2 = A_q_buf.view(dtypes.fp4x2)
            A_scale_sh = scale_buf.view(sm, sn).view(dtypes.fp8_e8m0)

            if M >= 64:
                kernel_name = _KERNEL_192x128 if M > 64 else _KERNEL_32x128
                log2_ks = None
            elif K >= 4096:
                kernel_name = _KERNEL_32x128
                log2_ks = 3
            elif K >= 2048:
                kernel_name = _KERNEL_32x128
                log2_ks = 2
            elif K >= 1024:
                kernel_name = _KERNEL_32x128
                log2_ks = 1
            else:
                kernel_name = _KERNEL_32x128
                log2_ks = None

            return aiter.gemm_a4w4_asm(
                A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
                out_buf, kernel_name,
                bpreshuffle=True,
                log2_k_split=log2_ks,
            )

    x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A.contiguous())
    A_q_fp4x2 = x_fp4.view(dtypes.fp4x2)
    A_scale_sh = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)
    out = torch.empty(M, N, dtype=torch.bfloat16, device="cuda")
    kn = _KERNEL_192x128 if M > 64 else _KERNEL_32x128
    return aiter.gemm_a4w4_asm(
        A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
        out, kn, bpreshuffle=True, log2_k_split=None,
    )

