    SCALE_PER_K: tl.constexpr = BLOCK_K // 16

    # Group-M swizzle for L2 cache locality across CUs
    pid = tl.program_id(0)
    num_blocks_m = tl.cdiv(M, BLOCK_M)
    num_blocks_n = tl.cdiv(N, BLOCK_N)
    num_in_group = GROUP_SIZE_M * num_blocks_n
    group_id = pid // num_in_group
    first_m = group_id * GROUP_SIZE_M
    group_sz = min(num_blocks_m - first_m, GROUP_SIZE_M)
    pid_m = first_m + ((pid % num_in_group) % group_sz)
    pid_n = (pid % num_in_group) // group_sz

    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
    mask_m = offs_m < M
    mask_n = offs_n < N

    acc = tl.zeros([BLOCK_M, BLOCK_N], dtype=tl.float32)

    for k_start in range(0, K_HALF, BLOCK_K):
        offs_k = k_start + tl.arange(0, BLOCK_K)
        mask_k = offs_k < K_HALF
        offs_ks = (k_start // 16) + tl.arange(0, SCALE_PER_K)

        # A tile: [BLOCK_M, BLOCK_K] fp4x2, row-major (standard)
        a = tl.load(
            A_ptr + offs_m[:, None] * stride_a_m + offs_k[None, :] * stride_a_k,
            mask=mask_m[:, None] & mask_k[None, :], other=0,
        )
        # A scale: [BLOCK_M, SCALE_PER_K] e8m0, row-major
        a_scale = tl.load(
            A_scale_ptr + offs_m[:, None] * stride_as_m + offs_ks[None, :] * stride_as_k,
            mask=mask_m[:, None], other=0,
        )

        # B tile: [BLOCK_K, BLOCK_N] fp4x2
        # Load B_q[offs_n[n], offs_k[k]] as b_tile[k, n] — transposed strides, no CPU copy
        b = tl.load(
            B_ptr + offs_k[:, None] * stride_b_k + offs_n[None, :] * stride_b_n,
            mask=mask_k[:, None] & mask_n[None, :], other=0,
        )
        # B scale: [BLOCK_N, SCALE_PER_K] e8m0, N-first (gfx950 RHS scale requirement)
        b_scale = tl.load(
            B_scale_ptr + offs_n[:, None] * stride_bs_n + offs_ks[None, :] * stride_bs_k,
            mask=mask_n[:, None], other=0,
        )

        # Helion-validated tl.dot_scaled call for gfx950
        acc = tl.dot_scaled(a, a_scale, "e2m1", b, b_scale, "e2m1", acc=acc)

    tl.store(
        C_ptr + offs_m[:, None] * stride_c_m + offs_n[None, :] * stride_c_n,
        acc.to(tl.bfloat16),
        mask=mask_m[:, None] & mask_n[None, :],
    )


