    # Fallback: Triton inline quant (no HIP dependency)
    # dynamic_mxfp4_quant returns A_scale column-major (stride=(1,M)) — must contiguous() first
    from aiter.ops.triton.quant import dynamic_mxfp4_quant
    A_q_raw, A_scale_raw = dynamic_mxfp4_quant(A.contiguous())
    A_scale_u8 = A_scale_raw.contiguous().view(torch.uint8)
    C = torch.empty(M, N, dtype=torch.bfloat16, device=A.device)
    grid = lambda META: (
        triton.cdiv(M, META["BLOCK_M"]) * triton.cdiv(N, META["BLOCK_N"]),
    )
    _mxfp4_gemm_kernel[grid](
        A_q_raw, A_scale_u8,
        B_q_u8, B_scale,
        C,
        M, N, K_HALF,
        A_q_raw.stride(0), A_q_raw.stride(1),
        A_scale_u8.stride(0), A_scale_u8.stride(1),
        B_q_u8.stride(0), B_q_u8.stride(1),
        B_scale.stride(0), B_scale.stride(1),
        C.stride(0), C.stride(1),
    )
    return C

